ROOT.proceduredef:
CREATE PROCEDURE CDN.MobS_EksportKnt @CentrumID INT, -- ID centrum praw struktury firmy @OpeNumer INT, -- ID mobilnego sprzedawcy @TypEksportu INT, -- Typ eksportu (0 - różnicowy, 1 - pełny) @PackageSize INT, -- rozmiar paczki @PackageNumber INT -- numer paczki AS BEGIN DECLARE @Dzis INT DECLARE @TimeStamp INT DECLARE @Typ_GrK SMALLINT DECLARE @GrOTyp SMALLINT DECLARE @GrONumer INT DECLARE @OpiNumer INT DECLARE @Rejony TABLE (KtOTyp SMALLINT, KtONumer INT)
SET @Typ_GrK = -32 SELECT @Dzis = DATEDIFF(d,CONVERT(datetime,'18001228',112),CONVERT(datetime,GetDate(),112)) UPDATE CDN.PicoKonfig SET PcK_TSSynchrKnt = DATEDIFF(s,CONVERT(datetime,'19900101',112),CONVERT(datetime,GetDate(),112)) WHERE PcK_CentrumID=@CentrumID AND PcK_Typ=4 SELECT @GrOTyp=PcK_KnGETyp, @GrONumer=PcK_KnGENumer, @TimeStamp=PcK_TSSynchrKntPtw FROM CDN.PicoKonfig WHERE PcK_CentrumID=@CentrumID AND PcK_Typ=4
IF @GrOTyp = 944 BEGIN INSERT INTO @Rejony SELECT KtO_KntTyp, KtO_KntNumer FROM CDN.OpeKarty JOIN CDN.KntOpiekun ON Ope_PrcNumer=KtO_PrcNumer WHERE Ope_GIDNumer=@OpeNumer AND (KtO_KntTyp=948 OR KtO_KntTyp=32) AND ((KtO_DataOd = 0 AND KtO_DataDo = 0) OR @Dzis BETWEEN KtO_DataOd AND KtO_DataDo); END
SELECT DISTINCT identity(int,1,1) AS Rank, * INTO #TempMobile FROM ( SELECT Knt.Knt_GIDNumer, CASE WHEN Knt.Knt_Typ IN(0,8,16,24) THEN Knt.Knt_Typ ELSE 0 END As Knt_Typ, Knt.Knt_Akronim As Knt_Akronim, ISNULL(Knt.Knt_Nazwa1,'') As Knt_Nazwa1, ISNULL(Knt.Knt_Nazwa2,'') As Knt_Nazwa2, ISNULL(Knt.Knt_Nazwa3,'') As Knt_Nazwa3, ISNULL(Knt.Knt_Kodp,'') As Knt_Kodp, ISNULL(Knt.Knt_Miasto,'') As Knt_Miasto, ISNULL(Knt.Knt_Wojewodztwo,'') As Knt_Wojewodztwo, ISNULL(Knt.Knt_Ulica,'') As Knt_Ulica, ISNULL(Knt.Knt_NipE,'') As Knt_NipE, ISNULL(Knt.Knt_NipPrefiks,'') As Knt_NipPrefiks, ISNULL(Knt.Knt_Regon,'') As Knt_Regon, ISNULL(Knt.Knt_Pesel,'') As Knt_Pesel, ISNULL(Knt.Knt_Telefon1,'') As Knt_Telefon1, ISNULL(Knt.Knt_Telefon2,'') As Knt_Telefon2, ISNULL(Knt.Knt_Fax,'') As Knt_Fax, ISNULL(Knt.Knt_Email,'') As Knt_Email, ISNULL(Knt.Knt_URL,'') As Knt_URL, ISNULL(Knt.Knt_Telex,'') As Knt_GSM, ISNULL(Knt.Knt_RegionCRM,0) As Knt_RegionCRM, ISNULL(Knt.Knt_PlatnikVat,0) As Knt_PlatnikVat, ISNULL(Knt.Knt_Rodzaj,0) As Knt_Rodzaj, ISNULL(Knt.Knt_Status,1) As Knt_Status, (CASE WHEN ISNULL(Knt.Knt_BlokadaTransakcji,0)=0 THEN 0 ELSE Knt.Knt_LastTransLockDate END) As Knt_LastTransLockDate, ISNULL(Knt.Knt_MaxDniPoTerminie,0) As Knt_MaxDniPoTerminie, CASE WHEN ISNULL(Knt.Knt_KnPParam,0)=1 THEN (ISNULL(KnP.Knt_FormaPl,10)) ELSE ISNULL(Knt.Knt_FormaPl,10)END As Knt_FormaPl, ISNULL(co.Naz_GIDLp,0) As Knt_CechaOpisId, ISNULL(sd.Naz_GIDLp,0) As Knt_SposobDostawyId, ISNULL(Knt.Knt_Cena,0) As Knt_Cena, CASE WHEN ISNULL(Knt.Knt_KnPParam,0)=1 THEN (ISNULL(KnP.Knt_LimitOkres,10)) ELSE ISNULL(Knt.Knt_LimitOkres,0)END As Knt_LimitOkres, ISNULL(Knt.Knt_Archiwalny,0) As Knt_Archiwalny, ISNULL(Knt.Knt_KnGNumer,Knt.Knt_GIDNumer) As Knt_KnGNumer, ISNULL(Knt.Knt_KnPNumer,Knt.Knt_GIDNumer) As Knt_KnPNumer, ISNULL(Knt.Knt_KnPParam,0) As Knt_KnPParam, ISNULL(Knt.Knt_KnANumer,0) As Knt_KnANumer, 1 As Knt_KontrahentTegoPH FROM CDN.KntKarty Knt JOIN CDN.KntKarty KnP ON KnP.Knt_GIDNumer=Knt.Knt_KnPNumer JOIN CDN.KntLinki ON KnL_GIDTyp=Knt.Knt_GIDTyp and KnL_GIDNumer=Knt.Knt_GIDNumer LEFT JOIN CDN.Nazwy co ON co.Naz_GIDTyp = 2720 AND rtrim(co.Naz_Nazwa)=rtrim(Knt.Knt_CechaOpis) LEFT JOIN CDN.Nazwy sd ON sd.Naz_GIDTyp = 976 AND rtrim(sd.Naz_Nazwa)=rtrim(Knt.Knt_SposobDostawy) WHERE Knt.Knt_Aktywna=0 AND Knt.Knt_GIDNumer>0 AND Knt.Knt_LastModC > CASE WHEN @TypEksportu=0 THEN @TimeStamp ELSE 0 END AND Knt.Knt_Archiwalny<CASE WHEN @TypEksportu=0 THEN 2 ELSE 1 END AND (KnL_GrOTyp=@Typ_GrK AND KnL_GrONumer = CASE WHEN @GrOTyp=@Typ_GrK THEN @GrONumer ELSE 0 END AND --((Knt.Knt_RegionCRM IN (SELECT KtONumer FROM @Rejony WHERE KtOTyp=948) OR Knt.Knt_GIDNumer IN (SELECT KtONumer FROM @Rejony WHERE KtOTyp=32))OR @GrOTyp=@Typ_GrK)) (EXISTS ( SELECT * FROM @Rejony JOIN CDN.KntRejony ON KnR_KntNumer = Knt.Knt_GIDNumer AND KtONumer = KnR_Rejon WHERE KtOTyp=948 ) OR EXISTS ( SELECT * FROM @Rejony WHERE KtOTyp=32 AND KtONumer = Knt.Knt_GIDNumer ) OR @GrOTyp=@Typ_GrK )) UNION SELECT Knt.Knt_GIDNumer, CASE WHEN Knt.Knt_Typ IN(0,8,16,24) THEN Knt.Knt_Typ ELSE 0 END As Knt_Typ, Knt.Knt_Akronim, ISNULL(Knt.Knt_Nazwa1,'') As Knt_Nazwa1, ISNULL(Knt.Knt_Nazwa2,'') As Knt_Nazwa2, ISNULL(Knt.Knt_Nazwa3,'') As Knt_Nazwa3, ISNULL(Knt.Knt_Kodp,'') As Knt_Kodp, ISNULL(Knt.Knt_Miasto,'') As Knt_Miasto, ISNULL(Knt.Knt_Wojewodztwo,'') As Knt_Wojewodztwo, ISNULL(Knt.Knt_Ulica,'') As Knt_Ulica, ISNULL(Knt.Knt_NipE,'') As Knt_NipE, ISNULL(Knt.Knt_NipPrefiks,'') As Knt_NipPrefiks, ISNULL(Knt.Knt_Regon,'') As Knt_Regon, ISNULL(Knt.Knt_Pesel,'') As Knt_Pesel, ISNULL(Knt.Knt_Telefon1,'') As Knt_Telefon1, ISNULL(Knt.Knt_Telefon2,'') As Knt_Telefon2, ISNULL(Knt.Knt_Fax,'') As Knt_Fax, ISNULL(Knt.Knt_Email,'') As Knt_Email, ISNULL(Knt.Knt_URL,'') As Knt_URL, ISNULL(Knt.Knt_Telex,'') As Knt_GSM, ISNULL(Knt.Knt_RegionCRM,0) As Knt_RegionCRM, ISNULL(Knt.Knt_PlatnikVat,0) As Knt_PlatnikVat, ISNULL(Knt.Knt_Rodzaj,0) As Knt_Rodzaj, ISNULL(Knt.Knt_Status,1) As Knt_Status, (CASE WHEN ISNULL(Knt.Knt_BlokadaTransakcji,0)=0 THEN 0 ELSE Knt.Knt_LastTransLockDate END) As Knt_LastTransLockDate, ISNULL(Knt.Knt_MaxDniPoTerminie,0) As Knt_MaxDniPoTerminie, CASE WHEN ISNULL(Knt.Knt_KnPParam,0)=1 THEN (ISNULL(KnP.Knt_FormaPl,10)) ELSE ISNULL(Knt.Knt_FormaPl,10)END As Knt_FormaPl, ISNULL(co.Naz_GIDLp,0) As Knt_CechaOpisId, ISNULL(sd.Naz_GIDLp,0) As Knt_SposobDostawyId, ISNULL(Knt.Knt_Cena,0) As Knt_Cena, CASE WHEN ISNULL(Knt.Knt_KnPParam,0)=1 THEN (ISNULL(KnP.Knt_LimitOkres,10)) ELSE ISNULL(Knt.Knt_LimitOkres,0)END As Knt_LimitOkres, ISNULL(Knt.Knt_Archiwalny,0) As Knt_Archiwalny, ISNULL(Knt.Knt_KnGNumer,Knt.Knt_GIDNumer) As Knt_KnGNumer, ISNULL(Knt.Knt_KnPNumer,Knt.Knt_GIDNumer) As Knt_KnPNumer, ISNULL(Knt.Knt_KnPParam,0) As Knt_KnPParam, ISNULL(Knt.Knt_KnANumer,0) As Knt_KnANumer, 1 As Knt_KontrahentTegoPH FROM CDN.KntKarty Knt JOIN CDN.CRMWizytyNag ON Knt.Knt_GIDNumer=CWN_KntNumer JOIN CDN.KntKarty KnP ON KnP.Knt_GIDNumer=Knt.Knt_KnPNumer JOIN CDN.OpeKarty ON CWN_Obsluga=Ope_PrcNumer LEFT JOIN CDN.Nazwy co ON co.Naz_GIDTyp = 2720 AND rtrim(co.Naz_Nazwa)=rtrim(Knt.Knt_CechaOpis) LEFT JOIN CDN.Nazwy sd ON sd.Naz_GIDTyp = 976 AND rtrim(sd.Naz_Nazwa)=rtrim(Knt.Knt_SposobDostawy) WHERE Knt.Knt_GIDNumer>0 AND Ope_GIDNumer=@OpeNumer AND CWN_ZewnetrznyId<=0 AND CWN_Stan=2 ) TableTmp
/* Kontrahent domyślny na PA */ INSERT INTO #TempMobile SELECT DISTINCT KntPA.Knt_GIDNumer, CASE WHEN KntPA.Knt_Typ IN(0,8,16,24) THEN KntPA.Knt_Typ ELSE 0 END As Knt_Typ, KntPA.Knt_Akronim, ISNULL(KntPA.Knt_Nazwa1,'') As Knt_Nazwa1, ISNULL(KntPA.Knt_Nazwa2,'') As Knt_Nazwa2, ISNULL(KntPA.Knt_Nazwa3,'') As Knt_Nazwa3, ISNULL(KntPA.Knt_Kodp,'') As Knt_Kodp, ISNULL(KntPA.Knt_Miasto,'') As Knt_Miasto, ISNULL(KntPA.Knt_Wojewodztwo,'') As Knt_Wojewodztwo, ISNULL(KntPA.Knt_Ulica,'') As Knt_Ulica, ISNULL(KntPA.Knt_NipE,'') As Knt_NipE, ISNULL(KntPA.Knt_NipPrefiks,'') As Knt_NipPrefiks, ISNULL(KntPA.Knt_Regon,'') As Knt_Regon, ISNULL(KntPA.Knt_Pesel,'') As Knt_Pesel, ISNULL(KntPA.Knt_Telefon1,'') As Knt_Telefon1, ISNULL(KntPA.Knt_Telefon2,'') As Knt_Telefon2, ISNULL(KntPA.Knt_Fax,'') As Knt_Fax, ISNULL(KntPA.Knt_Email,'') As Knt_Email, ISNULL(KntPA.Knt_URL,'') As Knt_URL, ISNULL(KntPA.Knt_Telex,'') As Knt_GSM, ISNULL(KntPA.Knt_RegionCRM,0) As Knt_RegionCRM, ISNULL(KntPA.Knt_PlatnikVat,0) As Knt_PlatnikVat, ISNULL(KntPA.Knt_Rodzaj,0) As Knt_Rodzaj, ISNULL(KntPA.Knt_Status,1) As Knt_Status, (CASE WHEN ISNULL(KntPA.Knt_BlokadaTransakcji,0)=0 THEN 0 ELSE KntPA.Knt_LastTransLockDate END) As Knt_LastTransLockDate, ISNULL(KntPA.Knt_MaxDniPoTerminie,0) As Knt_MaxDniPoTerminie, ISNULL(KntPA.Knt_FormaPl,10) As Knt_FormaPl, ISNULL(co.Naz_GIDLp,0) As Knt_CechaOpisId, ISNULL(sd.Naz_GIDLp,0) As Knt_SposobDostawyId, ISNULL(KntPA.Knt_Cena,0) As Knt_Cena, ISNULL(KntPA.Knt_LimitOkres,0) As Knt_LimitOkres, ISNULL(KntPA.Knt_Archiwalny,0) As Knt_Archiwalny, ISNULL(KntPA.Knt_KnGNumer,KntPA.Knt_GIDNumer) As Knt_KnGNumer, ISNULL(KntPA.Knt_KnPNumer,KntPA.Knt_GIDNumer) As Knt_KnPNumer, ISNULL(KntPA.Knt_KnPParam,0) As Knt_KnPParam, ISNULL(KntPA.Knt_KnANumer,0) As Knt_KnANumer, case when (EXISTS ( SELECT * FROM @Rejony JOIN CDN.KntRejony ON KnR_KntNumer = KntPA.Knt_GIDNumer AND KtONumer = KnR_Rejon WHERE KtOTyp=948) OR EXISTS ( SELECT * FROM @Rejony WHERE KtOTyp=32 AND KtONumer = KntPA.Knt_GIDNumer )--OR @GrOTyp=@Typ_GrK OR EXISTS(SELECT * FROM CDN.KntKarty Knt1 JOIN CDN.KntLinki ON KnL_GIDTyp=Knt1.Knt_GIDTyp and KnL_GIDNumer=Knt1.Knt_GIDNumer WHERE Knt1.Knt_Aktywna=0 AND Knt1.Knt_GIDNumer>0 AND Knt1.Knt_LastModC > 0 AND Knt1.Knt_Archiwalny< 1 AND KnL_GrOTyp=@Typ_GrK AND KnL_GrONumer = CASE WHEN @GrOTyp=@Typ_GrK THEN @GrONumer ELSE 0 END AND Knt1.Knt_GIDNumer=KntPA.Knt_GIDNumer) OR EXISTS(SELECT * FROM CDN.KntKarty Knt2 JOIN CDN.CRMWizytyNag ON Knt2.Knt_GIDNumer=CWN_KntNumer JOIN CDN.OpeKarty ON CWN_Obsluga=Ope_PrcNumer WHERE Knt2.Knt_GIDNumer>0 AND Ope_GIDNumer=@OpeNumer AND CWN_ZewnetrznyId<=0 AND CWN_Stan=2 and Knt2.Knt_GIDNumer=KntPA.Knt_GIDNumer) ) then 1 else 0 end As Knt_KontrahentTegoPH FROM CDN.KntKarty KntPA JOIN CDN.DokDefinicje ON Dok_KntTyp = 32 AND KntPA.Knt_GIDNumer = Dok_KntNumer LEFT JOIN CDN.Nazwy co ON co.Naz_GIDTyp = 2720 AND rtrim(co.Naz_Nazwa)=rtrim(KntPA.Knt_CechaOpis) LEFT JOIN CDN.Nazwy sd ON sd.Naz_GIDTyp = 976 AND rtrim(sd.Naz_Nazwa)=rtrim(KntPA.Knt_SposobDostawy) WHERE KntPA.Knt_GIDNumer > 0 AND Dok_GIDTyp=2034 AND Dok_FrsId=@CentrumID AND NOT EXISTS (SELECT * FROM #TempMobile WHERE Knt_GIDNumer = KntPA.Knt_GIDNumer)
/*Kontrahenci główni*/ INSERT INTO #TempMobile SELECT DISTINCT KnG.Knt_GIDNumer, CASE WHEN KnG.Knt_Typ IN(0,8,16,24) THEN KnG.Knt_Typ ELSE 0 END As Knt_Typ, KnG.Knt_Akronim, ISNULL(KnG.Knt_Nazwa1,'') As Knt_Nazwa1, ISNULL(KnG.Knt_Nazwa2,'') As Knt_Nazwa2, ISNULL(KnG.Knt_Nazwa3,'') As Knt_Nazwa3, ISNULL(KnG.Knt_Kodp,'') As Knt_Kodp, ISNULL(KnG.Knt_Miasto,'') As Knt_Miasto, ISNULL(KnG.Knt_Wojewodztwo,'') As Knt_Wojewodztwo, ISNULL(KnG.Knt_Ulica,'') As Knt_Ulica, ISNULL(KnG.Knt_NipE,'') As Knt_NipE, ISNULL(KnG.Knt_NipPrefiks,'') As Knt_NipPrefiks, ISNULL(KnG.Knt_Regon,'') As Knt_Regon, ISNULL(KnG.Knt_Pesel,'') As Knt_Pesel, ISNULL(KnG.Knt_Telefon1,'') As Knt_Telefon1, ISNULL(KnG.Knt_Telefon2,'') As Knt_Telefon2, ISNULL(KnG.Knt_Fax,'') As Knt_Fax, ISNULL(KnG.Knt_Email,'') As Knt_Email, ISNULL(KnG.Knt_URL,'') As Knt_URL, ISNULL(KnG.Knt_Telex,'') As Knt_GSM, ISNULL(KnG.Knt_RegionCRM,0) As Knt_RegionCRM, ISNULL(KnG.Knt_PlatnikVat,0) As Knt_PlatnikVat, ISNULL(KnG.Knt_Rodzaj,0) As Knt_Rodzaj, ISNULL(KnG.Knt_Status,1) As Knt_Status, (CASE WHEN ISNULL(KnG.Knt_BlokadaTransakcji,0)=0 THEN 0 ELSE KnG.Knt_LastTransLockDate END) As Knt_LastTransLockDate, ISNULL(KnG.Knt_MaxDniPoTerminie,0) As Knt_MaxDniPoTerminie, ISNULL(KnG.Knt_FormaPl,10) As Knt_FormaPl, ISNULL(co.Naz_GIDLp,0) As Knt_CechaOpisId, ISNULL(sd.Naz_GIDLp,0) As Knt_SposobDostawyId, ISNULL(KnG.Knt_Cena,0) As Knt_Cena, ISNULL(KnG.Knt_LimitOkres,0) As Knt_LimitOkres, ISNULL(KnG.Knt_Archiwalny,0) As Knt_Archiwalny, ISNULL(KnG.Knt_KnGNumer,KnG.Knt_GIDNumer) As Knt_KnGNumer, ISNULL(KnG.Knt_KnPNumer,KnG.Knt_GIDNumer) As Knt_KnPNumer, ISNULL(KnG.Knt_KnPParam,0) As Knt_KnPParam, ISNULL(KnG.Knt_KnANumer,0) As Knt_KnANumer, case when (EXISTS ( SELECT * FROM @Rejony JOIN CDN.KntRejony ON KnR_KntNumer = KnG.Knt_GIDNumer AND KtONumer = KnR_Rejon WHERE KtOTyp=948) OR EXISTS ( SELECT * FROM @Rejony WHERE KtOTyp=32 AND KtONumer = KnG.Knt_GIDNumer )--OR @GrOTyp=@Typ_GrK OR EXISTS(SELECT * FROM CDN.KntKarty Knt1 JOIN CDN.KntLinki ON KnL_GIDTyp=Knt1.Knt_GIDTyp and KnL_GIDNumer=Knt1.Knt_GIDNumer WHERE Knt1.Knt_Aktywna=0 AND Knt1.Knt_GIDNumer>0 AND Knt1.Knt_LastModC > 0 AND Knt1.Knt_Archiwalny< 1 AND KnL_GrOTyp=@Typ_GrK AND KnL_GrONumer = CASE WHEN @GrOTyp=@Typ_GrK THEN @GrONumer ELSE 0 END AND Knt1.Knt_GIDNumer=KnG.Knt_GIDNumer) OR EXISTS(SELECT * FROM CDN.KntKarty Knt2 JOIN CDN.CRMWizytyNag ON Knt2.Knt_GIDNumer=CWN_KntNumer JOIN CDN.OpeKarty ON CWN_Obsluga=Ope_PrcNumer WHERE Knt2.Knt_GIDNumer>0 AND Ope_GIDNumer=@OpeNumer AND CWN_ZewnetrznyId<=0 AND CWN_Stan=2 and Knt2.Knt_GIDNumer=KnG.Knt_GIDNumer) ) then 1 else 0 end As Knt_KontrahentTegoPH FROM CDN.KntKarty KnG JOIN #TempMobile Tmp ON Tmp.Knt_KnGNumer = KnG.Knt_GIDNumer LEFT JOIN CDN.Nazwy co ON co.Naz_GIDTyp = 2720 AND rtrim(co.Naz_Nazwa)=rtrim(KnG.Knt_CechaOpis) LEFT JOIN CDN.Nazwy sd ON sd.Naz_GIDTyp = 976 AND rtrim(sd.Naz_Nazwa)=rtrim(KnG.Knt_SposobDostawy) WHERE NOT EXISTS (SELECT * FROM #TempMobile WHERE Knt_GIDNumer = KnG.Knt_GIDNumer)
/*Płatnicy*/ INSERT INTO #TempMobile SELECT DISTINCT KnP.Knt_GIDNumer, CASE WHEN KnP.Knt_Typ IN(0,8,16,24) THEN KnP.Knt_Typ ELSE 0 END As Knt_Typ, KnP.Knt_Akronim, ISNULL(KnP.Knt_Nazwa1,'') As Knt_Nazwa1, ISNULL(KnP.Knt_Nazwa2,'') As Knt_Nazwa2, ISNULL(KnP.Knt_Nazwa3,'') As Knt_Nazwa3, ISNULL(KnP.Knt_Kodp,'') As Knt_Kodp, ISNULL(KnP.Knt_Miasto,'') As Knt_Miasto, ISNULL(KnP.Knt_Wojewodztwo,'') As Knt_Wojewodztwo, ISNULL(KnP.Knt_Ulica,'') As Knt_Ulica, ISNULL(KnP.Knt_NipE,'') As Knt_NipE, ISNULL(KnP.Knt_NipPrefiks,'') As Knt_NipPrefiks, ISNULL(KnP.Knt_Regon,'') As Knt_Regon, ISNULL(KnP.Knt_Pesel,'') As Knt_Pesel, ISNULL(KnP.Knt_Telefon1,'') As Knt_Telefon1, ISNULL(KnP.Knt_Telefon2,'') As Knt_Telefon2, ISNULL(KnP.Knt_Fax,'') As Knt_Fax, ISNULL(KnP.Knt_Email,'') As Knt_Email, ISNULL(KnP.Knt_URL,'') As Knt_URL, ISNULL(KnP.Knt_Telex,'') As Knt_GSM, ISNULL(KnP.Knt_RegionCRM,0) As Knt_RegionCRM, ISNULL(KnP.Knt_PlatnikVat,0) As Knt_PlatnikVat, ISNULL(KnP.Knt_Rodzaj,0) As Knt_Rodzaj, ISNULL(KnP.Knt_Status,1) As Knt_Status, (CASE WHEN ISNULL(KnP.Knt_BlokadaTransakcji,0)=0 THEN 0 ELSE KnP.Knt_LastTransLockDate END) As Knt_LastTransLockDate, ISNULL(KnP.Knt_MaxDniPoTerminie,0) As Knt_MaxDniPoTerminie, ISNULL(KnP.Knt_FormaPl,10) As Knt_FormaPl, ISNULL(co.Naz_GIDLp,0) As Knt_CechaOpisId, ISNULL(sd.Naz_GIDLp,0) As Knt_SposobDostawyId, ISNULL(KnP.Knt_Cena,0) As Knt_Cena, ISNULL(KnP.Knt_LimitOkres,0) As Knt_LimitOkres, ISNULL(KnP.Knt_Archiwalny,0) As Knt_Archiwalny, ISNULL(KnP.Knt_KnGNumer,KnP.Knt_GIDNumer) As Knt_KnGNumer, ISNULL(KnP.Knt_KnPNumer,KnP.Knt_GIDNumer) As Knt_KnPNumer, ISNULL(KnP.Knt_KnPParam,0) As Knt_KnPParam, ISNULL(KnP.Knt_KnANumer,0) As Knt_KnANumer, case when (EXISTS ( SELECT * FROM @Rejony JOIN CDN.KntRejony ON KnR_KntNumer = KnP.Knt_GIDNumer AND KtONumer = KnR_Rejon WHERE KtOTyp=948) OR EXISTS ( SELECT * FROM @Rejony WHERE KtOTyp=32 AND KtONumer = KnP.Knt_GIDNumer )--OR @GrOTyp=@Typ_GrK OR EXISTS(SELECT * FROM CDN.KntKarty Knt1 JOIN CDN.KntLinki ON KnL_GIDTyp=Knt1.Knt_GIDTyp and KnL_GIDNumer=Knt1.Knt_GIDNumer WHERE Knt1.Knt_Aktywna=0 AND Knt1.Knt_GIDNumer>0 AND Knt1.Knt_LastModC > 0 AND Knt1.Knt_Archiwalny< 1 AND KnL_GrOTyp=@Typ_GrK AND KnL_GrONumer = CASE WHEN @GrOTyp=@Typ_GrK THEN @GrONumer ELSE 0 END AND Knt1.Knt_GIDNumer=KnP.Knt_GIDNumer) OR EXISTS(SELECT * FROM CDN.KntKarty Knt2 JOIN CDN.CRMWizytyNag ON Knt2.Knt_GIDNumer=CWN_KntNumer JOIN CDN.OpeKarty ON CWN_Obsluga=Ope_PrcNumer WHERE Knt2.Knt_GIDNumer>0 AND Ope_GIDNumer=@OpeNumer AND CWN_ZewnetrznyId<=0 AND CWN_Stan=2 and Knt2.Knt_GIDNumer=KnP.Knt_GIDNumer) ) then 1 else 0 end As Knt_KontrahentTegoPH FROM CDN.KntKarty KnP JOIN #TempMobile Tmp ON Tmp.Knt_KnPNumer = KnP.Knt_GIDNumer LEFT JOIN CDN.Nazwy co ON co.Naz_GIDTyp = 2720 AND rtrim(co.Naz_Nazwa)=rtrim(KnP.Knt_CechaOpis) LEFT JOIN CDN.Nazwy sd ON sd.Naz_GIDTyp = 976 AND rtrim(sd.Naz_Nazwa)=rtrim(KnP.Knt_SposobDostawy) WHERE NOT EXISTS (SELECT * FROM #TempMobile WHERE Knt_GIDNumer = KnP.Knt_GIDNumer)
SELECT COUNT(*) FROM #TempMobile
DELETE FROM #TempMobile WHERE Rank <= @packageSize * (@packageNumber - 1) OR Rank > @packageSize * @packageNumber
SELECT * FROM #TempMobile
/*Atrybuty*/ SELECT Atr_Id, Atr_ObiNumer, CASE WHEN AtK_Typ = 1 THEN CASE WHEN Atr_Wartosc = 'TAK' THEN 'True' WHEN Atr_Wartosc = 'NIE' THEN 'False' ELSE '' END WHEN AtK_Format='@d17' THEN CASE WHEN CONVERT(int, Atr_Wartosc) = 0 THEN '' ELSE CONVERT(varchar, CDN.TsToDate(CONVERT(int, Atr_Wartosc), 0), 105) END WHEN Atr_Wartosc = '<Brak>' THEN '' ELSE Atr_Wartosc END AS Atr_Wartosc, 0 as Atr_WartoscId, Atr_AtKId FROM CDN.Atrybuty JOIN #TempMobile Tmp ON Atr_ObiNumer=Tmp.Knt_GidNumer AND Atr_ObiTyp = 32 JOIN CDN.AtrybutyKlasy ON Atr_AtKId = AtK_ID WHERE Knt_KontrahentTegoPH=1 AND AtK_MOBSPrawa>0 AND AtK_Typ <=6 /*Atrybuty koniec*/
SET NOCOUNT ON --Oznaczenie kontrahentów UPDATE CDN.KntKarty SET Knt_Oddzialowy=1 FROM CDN.KntKarty Knt JOIN #TempMobile Tmp ON Knt.Knt_GIDNumer=Tmp.Knt_GIDNumer WHERE Knt.Knt_Oddzialowy=0
DROP TABLE #TempMobile SET NOCOUNT OFF END
